import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/faq.md","filePath":"de/guide/faq.md","lastUpdated":1793173149000}`),a={name:`de/guide/faq.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h1><p>F: Was ist Sudoku?</p><p>A: Sudoku ist das klassische Logikrätsel zum Platzieren von Zahlen, neu gedacht für moderne Apple-Geräte. Füllen Sie ein 9×9-Gitter so, dass jede Zeile, jede Spalte und jeder 3×3-Block die Ziffern 1–9 genau einmal enthält. Es ist eine universelle App für iPhone, iPad und Mac mit iCloud-Synchronisierung.</p><p>F: Welche Geräte werden unterstützt?</p><p>A: Sudoku ist eine universelle App, optimiert für iPhone, iPad und Mac, mit nativen Bedienelementen und gestochen scharfer Retina-Grafik. Voraussetzung sind iOS/iPadOS 16.0 oder neuer sowie macOS 15.0 (Sequoia) oder neuer. Ein Kauf gilt auf allen unterstützten Geräten.</p><p>F: Wie lade ich Sudoku herunter und installiere es?</p><p>A: Laden Sie Sudoku im App Store herunter: <a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793606018</a> — die universelle App funktioniert auf iPhone, iPad und Mac.</p><p>F: Benötigt Sudoku eine Internetverbindung?</p><p>A: Das Kernspiel ist zu 100 % offline – zum Lösen der Rätsel ist kein Internet erforderlich. Optionale Funktionen mit Internetbedarf sind die iCloud-Synchronisierung (geräteübergreifender Fortschritt), Game Center (Ranglisten/Erfolge) und der Bereich „Weitere Apps“ in den Einstellungen.</p><p>F: Gibt es Werbung oder In-App-Käufe?</p><p>A: Nein. Sudoku ist vollständig werbefrei, ohne Pop-ups, ohne In-App-Käufe und ohne Unterbrechungen. Nur pures, konzentriertes Rätselspiel.</p><p>F: Welche Schwierigkeitsgrade gibt es?</p><p>A: Fünf Schwierigkeitsgrade mit unterschiedlich vielen vorgegebenen Feldern:</p><ul><li><strong>Leicht</strong> — 45 Vorgaben (ideal für Einsteiger)</li><li><strong>Mittel</strong> — 36 Vorgaben (ausgewogene Herausforderung)</li><li><strong>Schwer</strong> — 31 Vorgaben (erfordert Schlussfolgerungstechniken)</li><li><strong>Experte</strong> — 27 Vorgaben (für erfahrene Löser)</li><li><strong>Meister</strong> — 24 Vorgaben (die ultimative Herausforderung)</li></ul><p>Jedes Rätsel wird individuell erzeugt – Sie spielen nie zweimal dasselbe Rätsel.</p><p>F: Werden meine Spieldaten zwischen Geräten synchronisiert?</p><p>A: Ja! Wenn Sie bei iCloud angemeldet sind, werden Spielstände, Statistiken, Einstellungen und Fortschritte bei täglichen Herausforderungen über CloudKit automatisch auf allen Ihren Apple-Geräten synchronisiert.</p><p>F: Speichert Sudoku meinen Fortschritt, wenn ich die App beende?</p><p>A: Ja. Ihre aktuelle Partie wird automatisch gespeichert, sodass Sie genau dort weiterspielen können, wo Sie aufgehört haben. Der Startbildschirm zeigt eine Karte „Fortsetzen“ mit Ihrem laufenden Rätsel.</p><p>F: Wie aktualisiere ich die App?</p><p>A: App-Store-Nutzer erhalten Updates automatisch. Um manuell zu prüfen, öffnen Sie den App Store und wechseln Sie zum Bereich Account → Updates.</p><p>F: Wie melde ich Fehler oder wünsche mir Funktionen?</p><p>A: Eröffnen Sie ein Issue im Projekt-Repository und geben Sie Gerätetyp, iOS-/macOS-Version, Sudoku-Version, Schritte zum Reproduzieren und, falls vorhanden, Screenshots an.</p><p>F: Kann ich das Erscheinungsbild anpassen?</p><p>A: Ja! Wählen Sie in den Einstellungen aus 8 wunderschönen Designs (Classic, Midnight, Paper, Forest, Ocean, Sunset, Lavender, Rose). Außerdem können Sie die Soundeffekte ein- und ausschalten.</p><p>F: Wie viele Sprachen werden unterstützt?</p><p>A: 25 Sprachen, die zur Laufzeit ohne Neustart gewechselt werden können: Englisch, Chinesisch (vereinfacht und traditionell), Japanisch, Koreanisch, Französisch, Deutsch, Spanisch, Italienisch, Russisch, Portugiesisch, Niederländisch, Vietnamesisch, Thailändisch, Hindi, Türkisch, Griechisch, Finnisch, Norwegisch, Dänisch, Ungarisch, Indonesisch, Malaiisch, Ukrainisch und Deutsch (Schweiz).</p><p>F: Welche Tastaturkürzel gibt es auf dem Mac?</p><p>A: <code>⌘N</code> für ein neues Spiel, <code>⌘Z</code> zum Rückgängigmachen und <code>⌘1</code> bis <code>⌘5</code>, um ein neues Spiel im jeweiligen Schwierigkeitsgrad (Leicht bis Meister) zu starten.</p><p>F: Kann ich Rätsel drucken?</p><p>A: Ja! Nutzen Sie auf dem Mac die Druckfunktion, um druckbare Rätsel in jedem Schwierigkeitsgrad zu erzeugen, optional mit Lösungen.</p><p>Wenn Sie weitere Antworten benötigen, eröffnen Sie bitte ein Issue im Repository oder ziehen Sie die vollständige Dokumentation zu Rate.</p>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};